from pathlib import Path
import json,wave
root=Path(__file__).resolve().parent/'ml'/'data';root.mkdir(exist_ok=True)
training={'water':['water supply stopped','paani nahi aa raha','water pipe leaking','paani ka pipe toot gaya','no drinking water','tap has no water','jal supply band hai','water leak outside'],'electricity':['power cut since morning','bijli nahi hai','electric wire broken','light nahi aa rahi','streetlight broken','electricity supply failed','bijli ka taar gira','no power at home'],'roads':['road has potholes','sadak par gaddha hai','road surface damaged','sadak toot gayi','pothole near crossing','broken pavement','gali ki sadak kharab','repair the road'],'sanitation':['garbage not collected','kachra pada hai','drain is blocked','naali band hai','waste collection missed','rubbish on street','kachra nahi uthaya','sewage overflowing']}
(root/'train.json').write_text(json.dumps({'version':'synthetic-train-v1','synthetic':True,'examples':[{'text':t,'category':c} for c,ts in training.items() for t in ts]},indent=2))
examples=[('en','Water is leaking at Demo Lane.','water','Demo Lane',None,None),('hi-Latn-en','Bijli nahi hai at Sample Nagar since 2026-01-15.','electricity','Sample Nagar','2026-01-15',None),('hi-Latn-en','Sadak par gaddha hai near Test Road.','roads','Test Road',None,None),('hi-Latn-en','Kachra nahi uthaya at Fiction Park.','sanitation','Fiction Park',None,None),('en','The power supply failed near Mock Square. Name: Demo Person.','electricity','Mock Square',None,'Demo Person'),('en','A pothole appeared at Example Street on 2026-02-02.','roads','Example Street','2026-02-02',None),('en','Waste collection missed near Sample Park.','sanitation','Sample Park',None,None),('hi-Latn-en','Paani nahi aa raha at Demo Colony. ID: SYN-004.','water','Demo Colony',None,'SYN-004'),('en','The tap is dry at Imaginary Avenue.','water','Imaginary Avenue',None,None),('hi-Latn-en','Naali overflow ho rahi at Mock Lane.','sanitation','Mock Lane',None,None),('hi-Latn-en','Light chali gayi near Test Nagar.','electricity','Test Nagar',None,None),('en','The carriageway is fractured at Fiction Road.','roads','Fiction Road',None,None)]
rows=[]
for i,(lang,t,c,l,d,n) in enumerate(examples):
 rows.append({'id':f'syn-{i+1:03}','synthetic':True,'language':lang,'reference_transcript':t,'observed_transcript':t.replace('Demo Lane','Demo Line') if i==0 else t,'fields':{'category':c,'summary':t.split('.')[0],'location':l,'datetime':d,'identifier':n}})
(root/'eval.json').write_text(json.dumps({'version':'synthetic-eval-v1','synthetic':True,'examples':rows},indent=2))
with wave.open(str(root/'synthetic-silence.wav'),'wb') as w:
 w.setnchannels(1);w.setsampwidth(2);w.setframerate(16000);w.writeframes(b'\0\0'*16000)
